def compute(vars):
    gross_earnings = vars["Gross Earnings"]
    revenue = vars["Revenue"]
    cost_of_sales = -gross_earnings + revenue
    return {
        "value": cost_of_sales,
        "trace": {
            "Gross Earnings": gross_earnings,
            "Revenue": revenue,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
